import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"采集模型","description":"Mobile Inspector development documentation · 采集模型","frontmatter":{"title":"采集模型","description":"Mobile Inspector development documentation · 采集模型"},"headers":[],"relativePath":"zh/guide/capture-model.md","filePath":"zh/guide/capture-model.md"}'),i={name:"zh/guide/capture-model.md"};function n(l,e,p,d,c,s){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="采集模型" tabindex="-1">采集模型 <a class="header-anchor" href="#采集模型" aria-label="Permalink to &quot;采集模型&quot;">​</a></h1><p>Mobile Inspector 观察应用已有 Transport，不替换业务传输、不二次读取流，也不负责业务重试。</p><h2 id="显式生命周期" tabindex="-1">显式生命周期 <a class="header-anchor" href="#显式生命周期" aria-label="Permalink to &quot;显式生命周期&quot;">​</a></h2><p>SDK 创建后保持停止。停止时配置配对并确认非秘密目标，再通过独立用户动作开始记录。开始会创建新的采集代次；停止保留有界记录，但使旧句柄和发送队列失效。清除会停止、失效回调、清空内存，并尝试清除配对远端。断开移除诊断传输配置。</p><p>换号或切换环境时，先清除并断开，再开展新工作。旧代次的迟到回调不得写入新账号。关闭面板本身不代表停止采集。</p><h2 id="一次读取与观察" tabindex="-1">一次读取与观察 <a class="header-anchor" href="#一次读取与观察" aria-label="Permalink to &quot;一次读取与观察&quot;">​</a></h2><p>适配器只旁路观察业务消费者实际读取的字节。SSE 增量解析，未完成尾部丢弃。HTTP 状态、传输结束、取消与业务成功分别记录。二进制、文件与音频只保留摘要。原生日志需显式调用 SDK；JavaScript 可以包装 console 并保留原输出。</p><h2 id="有界证据" tabindex="-1">有界证据 <a class="header-anchor" href="#有界证据" aria-label="Permalink to &quot;有界证据&quot;">​</a></h2><p>默认最多保留 100 个请求、20,000 个事件和 8 MiB 序列化记录；单请求正文最多 1 MiB，SSE 帧最多 128 KiB。批次和队列也有上限。限制或缺口标记表示轨迹可能不完整。配对本身不会开启采集或诊断。</p><p>启用测试正文或导出日志前阅读<a href="./privacy">隐私说明</a>。</p>',10)])])}const _=a(i,[["render",n]]);export{u as __pageData,_ as default};
